public class TestCheckAddress extends BaseTest
{
        public void testCheckAddress()
        {
            var exchange = new Exchange(new HashMap<String, Object>() {{
                put( "id", "sampleexchange" );
            }});
            String address = "rDsbeomae4FXwgQTJp9Rs64Qg9vDiTCdBv";
            // currencies without a tag requirement pass with or without a tag
            Assert(java.util.Objects.equals(exchange.checkAddress(address, (String) null, (String) null), address));
            Assert(java.util.Objects.equals(exchange.checkAddress(address, "BTC", (String) null), address));
            // tag-required currencies need a tag
            Assert(java.util.Objects.equals(exchange.checkAddress(address, "XRP", "123456"), address));
            Assert(java.util.Objects.equals(exchange.checkAddress(address, "ATOM", "123456"), address));
            Boolean caught = false;
            try
            {
                exchange.checkAddress(address, "XRP", (String) null);
            } catch(Exception error)
            {
                caught = true;
            }
            Assert(caught, "XRP without a tag should have thrown");
            caught = false;
            try
            {
                exchange.checkAddress(address, "XLM", (String) null);
            } catch(Exception error)
            {
                caught = true;
            }
            Assert(caught, "XLM without a tag should have thrown");
            caught = false;
            try
            {
                exchange.checkAddress((String) null, "BTC", (String) null);
            } catch(Exception error)
            {
                caught = true;
            }
            Assert(caught, "an undefined address should have thrown");
        }
}